result = await mcp.call_tool("tools", "ox-bridge-edit", {"path": "qr.py", "edits": [{"old": "    # Form thin Q = H_0 H_1 ... H_{n-1} applied to e_1..e_n,
    # computed as Q^T = H_{n-1} ... H_0 acting on [I_n; 0].
    QT = np.zeros((n, m))
    QT[:, :n] = np.eye(n)
    for k in range(n - 1, -1, -1):
        v = V[k:, k]
        if not np.any(v):
            continue
        QT[:, k:] -= 2.0 * np.outer(v, v @ QT[:, k:])
    return QT.T, R", "new": "    # Form thin Q = H_0 H_1 ... H_{n-1} applied to e_1..e_n,
    # computed as Q^T = H_{n-1} ... H_0 acting on [I_n; 0] (m x n).
    W = np.zeros((m, n))
    W[:n, :] = np.eye(n)
    for k in range(n - 1, -1, -1):
        v = V[k:, k]
        if not np.any(v):
            continue
        W[k:, :] -= 2.0 * np.outer(v, v @ W[k:, :])
    return W.T.copy(), R"}]})
print(result)
